from rest_framework.views import APIView
from rest_framework.response import Response
from rest_framework import permissions, status
from taggit.models import TaggedItem

class ObjectTagDisassociateView(APIView):
    permission_classes = [permissions.IsAuthenticated]

    def delete(self, request, tagged_item_id):
        try:
            item = TaggedItem.objects.select_related('content_type').get(id=tagged_item_id)
        except TaggedItem.DoesNotExist:
            return Response({"error": "Tag mapping not found"}, status=status.HTTP_404_NOT_FOUND)

        # Verify that the underlying tagged object belongs to the user's tenant
        target_obj = item.content_object
        if not target_obj or getattr(target_obj, 'organization_id', None) != request.user.organization_id:
            return Response({"error": "Access denied"}, status=status.HTTP_403_FORBIDDEN)

        item.delete()
        return Response({"message": "Tag disassociated successfully"}, status=status.HTTP_200_OK)
